let lapse = 0;    // mouse timer

function Particle() {
  this.pos = createVector(random(width), random(height));
  this.vel = createVector(0, 0);
  this.acc = createVector(0, 0);
  this.maxspeed = 6;

  this.update = function() {
    this.vel.add(this.acc);
    this.vel.limit(this.maxspeed);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  this.prevPos = this.pos.copy();

  this.follow = function(vectors) {
    let x = floor(this.pos.x / scl);
    let y = floor(this.pos.y / scl);
    let index = x + y * cols;
    let force = vectors[index];
    this.applyForce(force);
  }

  this.applyForce = function(force) {
    this.acc.add(force);
  }

  this.show = function() {
    let r = map(this.pos.x, 0, width, 50, 255);
    let g = map(this.pos.y, 0, height, 50, 55);
    let b = map(this.pos.x / this.pos.y, 0, width / height, 50, 255);
    stroke(r, g, b, 50);
    //console.log(r);
    //circle(this.pos.x, this.pos.y, 4);
    //line(this.pos.x, this.pos.y, this.prevPos.x, this.prevPos.y);
    stroke(255, 255, 255, 10);
    line(this.pos.x, this.pos.y, this.prevPos.x, this.prevPos.y);
    stroke(r, g, b, 50);

    this.updatePrev();
  }

  this.updatePrev = function() {
    this.prevPos.x = this.pos.x;
    this.prevPos.y = this.pos.y;
  }

  this.edges = function() {
    if (this.pos.x > width) {
      this.pos.x = 0;
      this.updatePrev();
    }
    if (this.pos.x < 0) {
      this.pos.x = width;
      this.updatePrev();
    }
    if (this.pos.y > height) {
      this.pos.y = 0;
      this.updatePrev();
    }
    if (this.pos.y < 0) {
      this.pos.y = height;
      this.updatePrev();
    }
  }
}

let m = 0;
let inc = 0.1;
const scl = 10;
let cols, rows;
const particles = [];
let flowField = [];
let zoff = 0;

function isOdd(num) {
  return num % 2;
}
let noiseMax = .6;
let slider;
let phase = 0;

function setup() {
  createCanvas(1112, 834);
  // disable high density display
  // pixelDensity(1);
  cols = floor(width / scl);
  rows = floor(height / scl);
  flowField = new Array(cols * rows);
  for (let i = 0; i < 50; i++) {
    particles[i] = new Particle();
  }
  background(0);

}

function draw() {
  // Perlin Noise
  // let x = map(noise(m), 0, 1, 0, width);
  // let y = map(noise(m * 2), 0, 1, 0, height);
  let yoff = 0;
  for (let y = 0; y < rows; y++) {
    let xoff = 0;
    for (let x = 0; x < cols; x++) {
      var index = x + y * cols;
      var angle = noise(xoff, yoff, zoff) * TWO_PI;
      // A class to describe a two or three dimensional vector,      
      // specifically a Euclidean (also known as geometric) vector. A 
      // vector is an entity that has both magnitude and direction. The datatype, 
      // however, stores the components of the vector (x, y for 2D, and x, y, z for 3D). 
      // The magnitude and direction can be accessed via the methods mag() and heading().
      let v = p5.Vector.fromAngle(angle);
      v.setMag(7);
      flowField[index] = v;
      xoff += inc;
      strokeWeight(0.5);
      //push();
      // rotate(5);
      //vertex(x, y);
      //translate(x * scl, y * scl);
      //rotate(v.heading());
      line(0, 0, scl, 1);
      //pop();
    }
    yoff += inc;
    zoff += 0.003;
  }
  m += 0.01;
  // strokeWeight(8);
  for (let i = 0; i < particles.length; i++) {
    particles[i].follow(flowField);
    particles[i].update();
    particles[i].edges();
    particles[i].show();
    strokeWeight(0.25);

  }
  translate(width / 2, height / 2);

  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.01) {
    var xoff = map(cos((4 * a)  + phase), -1, 1, 0, -noiseMax);
    var yoff = map(sin((4 * a) + phase), -1, 1, 0, -noiseMax);
    var r = map(noise(xoff, yoff), 0, 1, 10, 550);
    var x = r * sin(a);
    var y = r * tan(a);
    noFill();

    strokeWeight(.25);
    rotate(a + phase);
    vertex(x, y);
    vertex(x + a, y + a);
    vertex(x - a, y - a);
    //vertex(x * a, y * a);
  }
  phase += 0.01;
  endShape(CLOSE);
  //fill(0);
 circle(width / 2, height / 2, 50);
  setTimeout(() => {
    noLoop();
  },45000)
}

function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
}

